import json
import os
import sys
import time
import traceback

import numpy as np
from PIL import Image

sys.path.insert(0, '/opt/tools')
from rcb_client import Robot

r = Robot()
print('SPEC', json.dumps(r.spec()), flush=True)
count = 0

def save_result(res, tag):
    global count
    count += 1
    path = f'/app/output/{count:02d}_{tag}'
    os.makedirs(path, exist_ok=True)
    for cam, frame in res.last.items():
        Image.fromarray(frame).save(f'{path}/{cam}.png')
    if res.depth:
        for cam, depth in res.depth.items():
            np.save(f'{path}/{cam}_depth.npy', depth)
    with open(f'{path}/meta.json', 'w') as f:
        json.dump(res.meta, f, indent=2)
    print('RESULT', path, json.dumps({k:v for k,v in res.meta.items() if k not in ('proprio','cameras')}), flush=True)
    now = res.meta.get('proprio', {}).get('now')
    if now is not None:
        print('NOW', np.round(now, 4).tolist(), flush=True)
    return res

def obs(tag='obs', depth=False, seconds=0):
    return save_result(r.get_obs(cameras=('head_camera','front_camera','left_camera','right_camera','observer_camera'), include_depth=depth, seconds=seconds, video='none'), tag)

def ee(rows, tag='ee'):
    return save_result(r.submit('ee_pose', rows, cameras=('head_camera','front_camera','left_camera','right_camera','observer_camera'), video='none', note=tag), tag)

def jp(rows, dt=.05, tag='jp'):
    return save_result(r.submit('joint_position', rows, dt=dt, cameras=('head_camera','front_camera','left_camera','right_camera','observer_camera'), video='none', note=tag), tag)

last = obs('initial', True)
print('READY', flush=True)
for line in sys.stdin:
    try:
        exec(line, globals())
    except Exception:
        traceback.print_exc()
    print('READY', flush=True)

